public class Validation { public static boolean validName(String s){return s!=null&&!s.trim().isEmpty()&&s.matches("[A-Za-z .'-]{2,60}");} public static boolean validEmail(String s){return s!=null&&s.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");} public static boolean validPhone(String s){return s!=null&&s.matches("[0-9]{10}");} public static boolean validDiscount(double d){return d>=0&&d<=100;} }
